solution.javascript:
function findCheapestPrice(n, flights, src, dst, k) {
  let prices = Array(n).fill(Infinity); prices[src] = 0;
  for (let i = 0; i <= k; i++) {
    const next = [...prices];
    for (const [from, to, price] of flights) if (prices[from] + price < next[to]) next[to] = prices[from] + price;
    prices = next;
  }
  return prices[dst] === Infinity ? -1 : prices[dst];
}

solution.cpp:
int findCheapestPrice(int n, vector<vector<int>>& flights, int src, int dst, int k) {
    vector<int> prices(n, INT_MAX); prices[src] = 0;
    for (int i = 0; i <= k; i++) {
        vector<int> next = prices;
        for (auto& f : flights) if (prices[f[0]] != INT_MAX && prices[f[0]] + f[2] < next[f[1]]) next[f[1]] = prices[f[0]] + f[2];
        prices = next;
    }
    return prices[dst] == INT_MAX ? -1 : prices[dst];
}
